async function addAttachments(taskId,files){
 const t=data().tasks.find(t=>t.id===taskId);if(!t)return;const s=limits(),existing=(t.attachments||[]).reduce((n,a)=>n+(Number.isFinite(a?.size)?a.size:0),0);let sum=existing;const errors=[],accepted=[];
 for(const f of files){if(!f.size){errors.push(`${f.name}: arquivo vazio.`);continue;}if(f.size>s.fileLimitMB*1048576||sum+f.size>s.taskLimitMB*1048576){errors.push(`${f.name}: limite excedido. Não foi lido.`);continue;}if(f.type&&!/^[a-zA-Z0-9!#$&^_.+-]+\/[a-zA-Z0-9!#$&^_.+-]+$/.test(f.type)){errors.push(`${f.name}: MIME inválido.`);continue;}sum+=f.size;accepted.push(f);}
 const additions=[];for(const f of accepted){try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('falha de leitura'));reader.onabort=()=>reject(Error('leitura cancelada'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(f);});const a={id:id(),name:f.name,mimeType:f.type||'application/octet-stream',size:f.size,addedAt:now(),dataBase64:content};const err=attachmentError(a);if(err)throw Error(err);additions.push(a);}catch(e){errors.push(`${f.name}: ${e.message}`);}}
 // The task can be deleted while FileReader is pending; never resurrect it.
 if(data().tasks.includes(t)&&additions.length){t.attachments??=[];t.attachments.push(...additions);appendHistory(t,'Anexos adicionados: '+additions.map(a=>a.name).join(', '));render();await persist();}if(errors.length)showError(errors.join('\n'));
}
function renderCalendar() { renderPlanner(); }
