function calendarImport(date,mode){
 const {from,to}=periodFor(date,mode), last=new Date(to);last.setDate(last.getDate()-1);
 return `<details class="planner-extra"><summary>Importar ou atualizar calendário (.ics)</summary><p class="muted">Fuso: ${esc(localTZ)}. Importação somente leitura; não altera o Teams / Outlook.</p><div class="toolbar"><label>Origem<input id="ics-source" value="Teams / Outlook" maxlength="120"></label><label>De<input type="date" id="ics-from" value="${today(from)}"></label><label>Até (inclusive)<input type="date" id="ics-to" value="${today(last)}"></label><label>Arquivo .ics<input id="ics-file" type="file" accept=".ics,text/calendar"></label><button id="import-ics">Importar / atualizar</button></div>${(data().calendarImports||[]).map(i=>`<p class="muted">${esc(i.source)} • última importação ${esc(new Date(i.syncedAt).toLocaleString('pt-BR'))}</p>`).join('')}<details><summary>Como obter o arquivo</summary><p>No Outlook clássico: Arquivo → Salvar calendário. No Outlook na Web, procure Calendário → Calendários compartilhados → Publicar um calendário, se permitido pela empresa. Salve o arquivo ICS da mesma conta do Teams. Um link publicado pode ser acessível a outras pessoas.</p><p>Use o mesmo nome de origem ao atualizar. Até 20 MB e 366 dias por importação. Não há conexão OAuth configurada. Recorrências avançadas e fusos não reconhecidos são recusados com explicação.</p></details></details>`;
}
function bindPlanner(){
 if($('#agenda-type'))$('#agenda-type').onchange=e=>{agendaType=e.target.value;render();};
 document.querySelectorAll('[data-configure-reminders]').forEach(b=>b.onclick=showReminderPanel);
 const update=(date,mode)=>{agendaDate=date;agendaMode=mode;agendaSelected=date;render();};
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>update(plannerState().date,b.dataset.view));
 document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{const s=plannerState();update(movePeriod(s.date,s.mode,+b.dataset.period),s.mode);});
 document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{agendaSelected=b.dataset.day;render();const target=$('.day-detail');target?.focus({preventScroll:true});if(window.matchMedia?.('(max-width: 760px)').matches)target?.scrollIntoView({behavior:'smooth',block:'start'});});
 document.querySelectorAll('[data-add-day]').forEach(b=>b.onclick=()=>openEditor(b.dataset.kind,null,b.dataset.kind==='routines'?{day:new Date(b.dataset.addDay+'T12:00:00').getDay()}:{due:b.dataset.addDay}));
 document.querySelectorAll('[data-toggle-task]').forEach(b=>b.onclick=async()=>{const t=data().tasks.find(t=>t.id===b.dataset.toggleTask);t.status='concluído';appendHistory(t,'Status: concluído');render();await persist();});
 if($('#planner-today'))$('#planner-today').onclick=()=>update(today(),plannerState().mode);
 if($('#source-filter'))$('#source-filter').onchange=e=>{sourceFilter=e.target.value;render();};
}
function bindCalendar(){
 const button=$('#import-ics');if(!button)return;
 button.onclick=async e=>{const button=e.target;try{const f=$('#ics-file').files[0],source=$('#ics-source').value.trim(),start=$('#ics-from').value,last=$('#ics-to').value;if(!f||!source||!start||!last)throw Error('Escolha o arquivo, a origem e as duas datas.');if(f.size>20*1048576||!f.size)throw Error('O arquivo precisa ter entre 1 byte e 20 MB.');const from=new Date(start+'T00:00:00'),to=new Date(last+'T00:00:00');to.setDate(to.getDate()+1);if(to<=from||to-from>367*86400000)throw Error('Selecione um intervalo de até 366 dias.');button.disabled=true;const events=parseICS(await f.text(),{source,from:from.toISOString(),to:to.toISOString()});if(!events.length&&!await confirmAction('Nenhum evento neste intervalo. Continuar pode marcar eventos anteriores da mesma origem como indisponíveis.'))return;mergeEvents(data(),events,source,from.toISOString(),to.toISOString());render();await persist();}catch(err){showError('Importação não concluída: '+err.message);}finally{button.disabled=false;}};
}
// Session-only notification center. Preferences live in the selected JSON.
const reminderEngine=new ReminderEngine();
let reminderTimer=null,reminderAudio=null,reminderMessages=[],reminderNotice='';
function reminderText(item,live=false){const minutes=live?Math.max(0,Math.ceil((item.start-Date.now())/60000)):item.minutes,late=live?Math.max(0,Math.floor((Date.now()-item.start)/60000)):item.lateMinutes;
 if(item.kind==='task')return item.stage==='before'?`Prazo em ${minutes} min`:late?`Prazo passou há ${late} min`:'O prazo chegou';
 if(['topic','decision'].includes(item.kind))return item.stage==='before'?`Revisão em ${minutes} min`:late?`Revisão prevista há ${late} min`:'Hora de revisar';
 return item.stage==='before'?minutes?`Começa em ${minutes} min`:'Começando agora':late?`Começou há ${late} min`:'Começou agora';}

function reminderPanel(){
 const s=reminderSettings(data()),permission=typeof Notification==='undefined'?'indisponível':Notification.permission;
 return `<div class="dialog-head"><h2>Alertas de compromissos</h2><button class="secondary" id="close-reminders" aria-label="Fechar alertas">×</button></div><p class="reminder-help">Avisos da rotina, agenda, tarefas e revisões em qualquer tela. Mantenha o sistema aberto; computador suspenso, aba descartada ou restrições do navegador podem atrasar ou impedir os alertas.</p><form id="reminder-settings"><label class="reminder-toggle"><input name="enabled" type="checkbox" ${s.enabled?'checked':''}> Ativar alertas</label><div class="reminder-options"><label>Antecedência<select name="minutesBefore">${[5,10,15,30,60].map(n=>`<option value="${n}" ${n===s.minutesBefore?'selected':''}>${n} minutos antes</option>`).join('')}</select></label><label><input type="checkbox" name="routines" ${s.routines?'checked':''}> Blocos recorrentes</label><label><input type="checkbox" name="events" ${s.events?'checked':''}> Compromissos importados</label><label><input type="checkbox" name="work" ${s.work?'checked':''}> Tarefas, assuntos e feedbacks com horário</label><label><input type="checkbox" name="sound" ${s.sound?'checked':''}> Som nos alertas</label><label>Som da notificação<select name="soundId" id="reminder-sound">${Object.entries(reminderSounds).map(([key,sound])=>`<option value="${key}" ${(s.soundId||'classic')===key?'selected':''}>${esc(sound.label)}</option>`).join('')}</select></label><label class="reminder-volume-control" for="reminder-volume">Volume do som <output id="reminder-volume-value" for="reminder-volume">${s.volume}%</output><input type="range" id="reminder-volume" name="volume" min="0" max="100" step="1" value="${s.volume}" aria-label="Volume do som de notificação"></label><label><input type="checkbox" name="desktop" ${s.desktop?'checked':''}> Notificações do navegador</label></div><div class="reminder-buttons"><button type="button" class="secondary" id="permit-notifications">Permitir notificações</button><button type="button" class="secondary" id="test-reminder-sound">Testar som</button><button type="button" class="secondary" id="test-desktop-notification">Testar notificação desktop</button><button>Salvar preferências</button></div></form><p class="reminder-help" id="reminder-feedback" role="status">${esc(reminderNotice||`Notificações do navegador: ${permission}. O aviso visual funciona sem essa permissão.`)}</p><p class="reminder-help">Um aviso antes e outro no horário marcado. Rotinas sem duração não recebem alerta de término. Eventos de dia inteiro, cancelados ou indisponíveis não geram alertas. Ao reabrir o arquivo, ative o som com um clique se o navegador solicitar.</p><h3>Alertas desta sessão</h3><div id="reminder-history">${reminderMessages.slice().reverse().map(item=>`<article class="reminder-history-item"><strong>${esc(item.title)}</strong><p>${esc(reminderText(item))} • ${esc(item.source)} • ${esc(new Date(item.firedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}</p><button class="secondary" data-reminder-open="${esc(item.id)}">${item.kind==='feedback'?'Ver feedback':'Ver na agenda'}</button></article>`).join('')||'<p class="muted">Os próximos avisos aparecerão aqui.</p>'}</div>`;
}
function updateReminderIndicator(){
 const button=$('#reminders-button');if(button&&data())button.textContent=`Alertas ${reminderSettings(data()).enabled?'ativos':'desativados'}${reminderMessages.some(m=>!m.read)?' • '+reminderMessages.filter(m=>!m.read).length:''}`;
}
function showReminderPanel(){
 $('#reminders-dialog').innerHTML=reminderPanel();$('#reminders-dialog').showModal();bindReminderPanel();
}
async function unlockReminderAudio(){
 const Audio=window.AudioContext||window.webkitAudioContext;
 if(!Audio)throw Error('Este navegador não oferece áudio para alertas.');
 if(!reminderAudio||reminderAudio.state==='closed')reminderAudio=new Audio();
 await reminderAudio.resume();if(reminderAudio.state==='running'&&$('#reminder-audio-hint'))$('#reminder-audio-hint').hidden=true;if(reminderAudio.state!=='running')throw Error('Áudio bloqueado. Clique em “Testar som” e confira o volume do sistema.');
}
const reminderSounds={
 classic:{label:'Alerta clássico',wave:'triangle',notes:[[0,784],[.32,1046],[.64,784],[1.12,784],[1.44,1046],[1.76,784]]},
 bell:{label:'Campainha',wave:'sine',notes:[[0,1046],[.32,784],[.95,1046],[1.27,784]]},
 urgent:{label:'Alerta insistente',wave:'triangle',notes:[[0,880],[.30,660],[.60,880],[.90,660],[1.20,880],[1.50,660],[1.80,880]]},
 rising:{label:'Chamada crescente',wave:'triangle',notes:[[0,523],[.30,659],[.60,784],[.90,1046],[1.40,784],[1.70,1046]]},
 digital:{label:'Toque digital',wave:'square',notes:[[0,1175],[.32,880],[.64,1175],[1.12,1175],[1.44,880],[1.76,1175]]}
};
async function playReminderSound(soundId=reminderSettings(data()).soundId,volume=reminderSettings(data()).volume){
 const level=Math.max(0,Math.min(100,Number(volume)))/100;
 if(!Number.isFinite(level)||level===0)return;
 const peak=.65*level;
 const sound=reminderSounds[soundId]||reminderSounds.classic;
 await unlockReminderAudio();
 for(const [offset,frequency] of sound.notes){
  const tone=reminderAudio.createOscillator(),gain=reminderAudio.createGain(),start=reminderAudio.currentTime+offset;
  tone.type=sound.wave;tone.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(peak,start+.015);gain.gain.setValueAtTime(peak,start+.20);gain.gain.exponentialRampToValueAtTime(.001,start+.28);tone.connect(gain);gain.connect(reminderAudio.destination);tone.start(start);tone.stop(start+.30);tone.onended=()=>{tone.disconnect();gain.disconnect();};
 }
}
function reminderFeedback(text){reminderNotice=text;const field=$('#reminder-feedback');if(field)field.textContent=text;}
async function permitDesktopNotifications(){
 if(typeof Notification==='undefined')throw Error('Notificações desktop indisponíveis neste navegador.');
 const permission=Notification.permission==='default'?await Notification.requestPermission():Notification.permission;
 if(permission!=='granted')throw Error(permission==='denied'?'Notificações bloqueadas. Libere a permissão de notificações nas configurações do Chrome para este endereço.':'Autorize as notificações do Chrome para receber alertas desktop.');
}
function sendDesktopNotification(title,options){
 const notification=new Notification(title,{...options,silent:true});
 notification.onclick=()=>{window.focus();showReminderPanel();notification.close();};
 return notification;
}
function bindReminderPanel(){
 $('#close-reminders').onclick=()=>$('#reminders-dialog').close();
 $('#permit-notifications').onclick=async()=>{try{await permitDesktopNotifications();$('#reminder-settings').elements.desktop.checked=true;data().settings??={fileLimitMB:10,taskLimitMB:25};data().settings.reminders={...reminderSettings(data()),desktop:true};const saved=await persist();reminderFeedback(saved?'Notificações desktop permitidas e preferência salva.':'Notificações permitidas, mas houve falha ao salvar a preferência. Use Salvar agora.');}catch(e){reminderFeedback(e.message);}};
 $('#test-desktop-notification').onclick=async()=>{try{await permitDesktopNotifications();sendDesktopNotification('Techlead Desk — teste de notificação',{body:'Seus alertas também aparecerão aqui, na área de trabalho.',tag:'techlead-desk-test'});reminderFeedback('Notificação de teste enviada ao Chrome. Se não aparecer, confira as notificações do sistema e o modo Não perturbe.');}catch(e){reminderFeedback(e.message);}};
 $('#reminder-volume').oninput=e=>{$('#reminder-volume-value').textContent=e.target.value+'%';};
 $('#test-reminder-sound').onclick=async()=>{try{const volume=Number($('#reminder-volume').value);await playReminderSound($('#reminder-sound').value,volume);reminderFeedback(volume===0?'Volume em 0%: o som está silenciado.':'Som de teste reproduzido a '+volume+'%. Confira também o volume do sistema.');}catch(e){reminderFeedback(e.message);}};
 $('#reminder-settings').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),config={enabled:form.has('enabled'),minutesBefore:Number(form.get('minutesBefore')),sound:form.has('sound'),soundId:form.get('soundId')||'classic',volume:Number(form.get('volume')),desktop:form.has('desktop'),routines:form.has('routines'),events:form.has('events'),work:form.has('work')};if(![5,10,15,30,60].includes(config.minutesBefore)||!Number.isFinite(config.volume)||config.volume<0||config.volume>100)return;
 if(config.enabled&&config.desktop){try{await permitDesktopNotifications();}catch(err){reminderFeedback(err.message+' As preferências ainda não foram salvas.');return;}}
 if(config.enabled&&config.sound){try{await unlockReminderAudio();}catch(err){reminderFeedback(err.message);}}
 data().settings??={fileLimitMB:10,taskLimitMB:25};data().settings.reminders=config;
 if(!config.enabled){reminderMessages.forEach(m=>m.read=true);renderReminderToasts();}const saved=await persist();updateReminderIndicator();
 let message=saved?'Preferências salvas.':'Falha ao salvar; preferências mantidas apenas nesta sessão. Tente Salvar agora.';
 if(config.enabled&&config.desktop&&(typeof Notification==='undefined'||Notification.permission!=='granted'))message+=' Clique em Permitir notificações para autorizar os avisos do navegador.';
 if(config.enabled&&config.sound&&reminderAudio?.state!=='running')message+=' Som bloqueado: tente Testar som.';
 reminderFeedback(message);checkReminders();
 };
 bindReminderLinks();
}
function bindReminderLinks(){
 document.querySelectorAll('[data-reminder-open]').forEach(button=>button.onclick=async()=>{const item=reminderMessages.find(x=>x.id===button.dataset.reminderOpen);if(!item)return;item.read=true;if(item.kind==='feedback'){feedbackView='all';$('#reminders-dialog').close();await navigate('feedbacks');query=item.title;render();renderReminderToasts();return;}agendaDate=agendaSelected=item.date;agendaMode='day';sourceFilter='';agendaType='';$('#reminders-dialog').close();await navigate('calendar');renderReminderToasts();});
 document.querySelectorAll('[data-dismiss-reminder]').forEach(button=>button.onclick=()=>{const item=reminderMessages.find(x=>x.id===button.dataset.dismissReminder);if(item)item.read=true;renderReminderToasts();});
}
function renderReminderToasts(){
 const root=$('#reminder-toasts');if(!root)return;
 root.innerHTML=reminderMessages.filter(m=>!m.read).slice().reverse().map(item=>`<article class="reminder-toast ${item.stage==='started'?'started':''}"><span class="reminder-kicker" data-reminder-clock="${esc(item.id)}">${esc(reminderText(item,true))}</span><strong>${esc(item.title)}</strong><p>${esc(item.source)} • ${esc(new Date(item.start).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}</p><div><button class="secondary" data-reminder-open="${esc(item.id)}">${item.kind==='feedback'?'Ver feedback':'Ver na agenda'}</button><button class="quiet-button" data-dismiss-reminder="${esc(item.id)}" aria-label="Dispensar aviso de ${esc(item.title)}">Dispensar</button></div></article>`).join('');
 updateReminderIndicator();bindReminderLinks();
}
function checkReminders(){
 if(!data())return;const candidates=new Set(reminderCandidates(data()).map(c=>c.key));let changed=false;for(const m of reminderMessages){if(!m.read&&!candidates.has(m.key)){m.read=true;changed=true;}}if(changed)renderReminderToasts();const items=reminderEngine.poll(data());if(!items.length){document.querySelectorAll('[data-reminder-clock]').forEach(el=>{const item=reminderMessages.find(m=>m.id===el.dataset.reminderClock);if(item)el.textContent=reminderText(item,true);});return;}for(const item of items)if(item.stage==='started')for(const m of reminderMessages)if(m.key===item.key&&m.stage==='before')m.read=true;
 reminderMessages.push(...items);if(reminderMessages.length>100)reminderMessages=reminderMessages.slice(-100);renderReminderToasts();
 const settings=reminderSettings(data());
 if(settings.sound)playReminderSound().catch(()=>{reminderNotice='Som bloqueado. Abra Alertas e clique em Testar som.';const hint=$('#reminder-audio-hint');if(hint){hint.hidden=false;hint.textContent=reminderNotice;}});
 if(settings.desktop&&typeof Notification!=='undefined'&&Notification.permission==='granted')for(const item of items){try{sendDesktopNotification(`${reminderText(item)}: ${item.title}`,{body:item.source+' • '+new Date(item.start).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),tag:item.id});}catch(e){reminderFeedback('O navegador não conseguiu mostrar a notificação desktop. O aviso visual continua disponível.');}}
}
function startReminders(){
 updateReminderIndicator();if(reminderTimer!==null)return;
 reminderTimer=window.setInterval(checkReminders,5000);checkReminders();
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkReminders();});window.addEventListener('focus',checkReminders);
}

async function start(action){$('#welcome-error').textContent='';try{if(action==='open'){const [h]=await window.showOpenFilePicker({types:[{description:'Dados Techlead Desk',accept:{'application/json':['.json']}}],multiple:false});const permission=await h.requestPermission({mode:'readwrite'});if(permission!=='granted')throw Error('Permissão de leitura e escrita negada. O painel continua bloqueado.');const warnings=await store.open(h);const migrated=migrateLegacyDecisions(data());activate();if(migrated)await persist();if(warnings.length)showError(warnings.join('\n'));}else{const h=await window.showSaveFilePicker({suggestedName:'techlead-desk.json',types:[{description:'Dados Techlead Desk',accept:{'application/json':['.json']}}]});await store.create(h);activate();}}catch(e){if(e.name!=='AbortError')$('#welcome-error').textContent='Não foi possível abrir/criar o arquivo: '+e.message;}}
function activate(){$('#filename').textContent=store.handle.name;$('#save-status').textContent='Arquivo pronto • sem alterações pendentes';$('#app').hidden=false;$('#app').inert=false;$('#welcome').hidden=true;render();focusPageTop();startReminders();}
const supported=window.isSecureContext&&typeof window.showOpenFilePicker==='function'&&typeof window.showSaveFilePicker==='function';
if(!supported){$('#welcome-error').textContent='Este aplicativo requer Chrome ou Edge atualizado em localhost ou HTTPS, com suporte à File System Access API. O painel ficará bloqueado para proteger seus dados.';$('#open').disabled=$('#create').disabled=true;}
$('#open').onclick=()=>start('open');$('#create').onclick=()=>start('create');$('#save').onclick=async()=>{try{await store.flush();if(!store.dirty)$('#save-status').textContent='Arquivo salvo • '+new Date().toLocaleTimeString('pt-BR');}catch{}};
$('#menu').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');}if((e.ctrlKey||e.metaKey)&&e.key==='s'&&store.data){e.preventDefault();$('#save').click();}});
window.addEventListener('beforeunload',e=>{if(store.dirty||pendingAttachments){e.preventDefault();e.returnValue='';}});

if($('#reminders-button'))$('#reminders-button').onclick=showReminderPanel;
